def acc(items,first_open=False,exclusive=None):
    o='<div class="acc2">'
    for i,(t,sub,bd,idd) in enumerate(items):
        o+='<details%s%s%s><summary><span>%s%s</span></summary><div class="bd">%s</div></details>'%((' id="%s"'%idd) if idd else '',' open' if (first_open and i==0) else '',(' name="%s"'%exclusive) if exclusive else '',t,('<span class="sm">%s</span>'%sub) if sub else '',bd)
    return o+'</div>'

